package iodatos
import("encoding/json";"fmt";"os";"strconv";"transporte/Internal/errores";"transporte/Internal/grafo";"transporte/Internal/modelos")
func CargarJSON(p string)(any,error){b,e:=os.ReadFile(p);if e!=nil{return nil,&errores.ErrorDatos{Mensaje:e.Error()}};var v any;if e=json.Unmarshal(b,&v);e!=nil{return nil,&errores.ErrorDatos{Mensaje:e.Error()}};return v,nil}
func arr(v any,keys ...string)([]any,error){if x,ok:=v.([]any);ok{return x,nil};if m,ok:=v.(map[string]any);ok{for _,k:=range keys{if x,ok:=m[k].([]any);ok{return x,nil}}};return nil,&errores.ErrorDatos{Mensaje:"Se esperaba una lista"}}
func st(m map[string]any,k ...string)string{for _,x:=range k{if v,ok:=m[x];ok{return fmt.Sprint(v)}};return ""};func nu(m map[string]any,k ...string)float64{for _,x:=range k{if v,ok:=m[x].(float64);ok{return v}};return 0}
func CargarGrafo(p string)(*grafo.Grafo,error){v,e:=CargarJSON(p);if e!=nil{return nil,e};g:=grafo.Nuevo();if m,ok:=v.(map[string]any);ok{if ns,ok:=m["nodos"].([]any);ok{for _,z:=range ns{if n,ok:=z.(map[string]any);ok{g.AgregarNodo(st(n,"id"))}}}};xs,e:=arr(v,"aristas","conexiones","rutas","edges");if e!=nil{return nil,e};for _,z:=range xs{m,ok:=z.(map[string]any);if !ok{return nil,&errores.ErrorDatos{Mensaje:"arista inválida"}};g.AgregarConexion(st(m,"origen","desde","from"),st(m,"destino","hasta","to"),nu(m,"distancia","peso","weight"),nu(m,"tiempo"),m["bidireccional"]!=false)};return g,nil}
func CargarSolicitudes(p string)([]modelos.Solicitud,error){v,e:=CargarJSON(p);if e!=nil{return nil,e};xs,e:=arr(v,"solicitudes","pedidos");if e!=nil{return nil,e};r:=[]modelos.Solicitud{};for i,z:=range xs{m,ok:=z.(map[string]any);if !ok{return nil,&errores.ErrorDatos{Mensaje:"solicitud inválida"}};id:=st(m,"id");if id==""{id=strconv.Itoa(i)};r=append(r,modelos.Solicitud{ID:id,Origen:st(m,"origen","desde"),Destino:st(m,"destino","hasta"),Peso:nu(m,"peso","demanda"),Prioridad:int(nu(m,"prioridad"))})};return r,nil}
func CargarVehiculos(p string)([]modelos.Vehiculo,error){v,e:=CargarJSON(p);if e!=nil{return nil,e};xs,e:=arr(v,"vehiculos","vehículos");if e!=nil{return nil,e};r:=[]modelos.Vehiculo{};for i,z:=range xs{m,ok:=z.(map[string]any);if !ok{return nil,&errores.ErrorDatos{Mensaje:"vehículo inválido"}};id:=st(m,"id");if id==""{id=strconv.Itoa(i)};speed:=nu(m,"velocidad");if speed==0{speed=1};avail:=true;if x,ok:=m["disponible"].(bool);ok{avail=x};r=append(r,modelos.Vehiculo{ID:id,Origen:st(m,"origen","ubicacion"),Capacidad:nu(m,"capacidad"),Velocidad:speed,Disponible:avail})};return r,nil}
func GuardarJSON(p string,v any)error{b,e:=json.MarshalIndent(v,"","  ");if e!=nil{return e};return os.WriteFile(p,b,0644)};var LeerJSON=CargarJSON;var LeerRed=CargarGrafo;var LeerSolicitudes=CargarSolicitudes;var LeerVehiculos=CargarVehiculos